<script lang="ts">
	import Search from '@lucide/svelte/icons/search';
	import Copy from '@lucide/svelte/icons/copy';
	import Check from '@lucide/svelte/icons/check';
	import ArrowUpRight from '@lucide/svelte/icons/arrow-up-right';
	import ProviderMark from './provider-mark.svelte';
	import EmptyState from './empty-state.svelte';
	import { copyText } from '$lib/clipboard';
	import { formatCount, formatDate, providerName, privateLabel, type Status, type Call, type Model, type Account, type Client } from '$lib/management';
	import { t } from '$lib/i18n.svelte';
	let { screen, summary, calls, models, accounts, clients = [], busy, toggleModel, navigate, showEmails = false }: { screen: string; summary: Status | null; calls: Call[]; models: Model[]; accounts: Account[]; clients?: Client[]; busy: string; toggleModel: (model: Model) => void; navigate: (screen: string) => void; showEmails?: boolean } = $props();
	let search = $state('');
	let onlyErrors = $state(false);
	let copied = $state(false);
	let copyFailure = $state('');
	let tool = $state('openai');
	let filteredModels = $derived(models.filter(m => `${m.id} ${m.name} ${m.provider}`.toLowerCase().includes(search.toLowerCase())));
	let clientNames = $derived(new Map(clients.map(client => [client.id, client.name])));
	let filteredCalls = $derived(calls.filter(c => (!onlyErrors || c.status >= 400 || c.error) && `${c.model} ${c.provider} ${c.account_id} ${c.client_id ? clientNames.get(c.client_id) ?? '' : ''}`.toLowerCase().includes(search.toLowerCase())));
	let successRate = $derived(summary?.requests ? Math.round((summary.requests-summary.errors)/summary.requests*100) : null);
	let baseUrl = $derived(summary?.client_api_base_url ?? (typeof window === 'undefined' ? '' : `${window.location.origin}/v1`));
	let claudeConfig = $derived(`$env:ANTHROPIC_BASE_URL = '${baseUrl.replace(/\/v1$/, '').replace(/'/g, "''")}'\n$env:ANTHROPIC_AUTH_TOKEN = 'dk_...'\nclaude`);
	async function copy(value: string) { try { await copyText(value); copied = true; copyFailure = ''; } catch { copied = false; copyFailure = t('common.copyRefused'); } }
</script>

{#if screen === 'overview'}
	<div class="page-heading"><div><h1>{t('nav.overview')}</h1><p class="page-description">{t('overview.description')}</p></div><span class="state-badge" class:inactive={!summary}><span class="status-pip"></span>{t(summary ? 'overview.connected' : 'overview.disconnected')}</span></div>
	<div class="overview-stats"><div><p>{t('overview.activeAccounts')}</p><strong>{summary ? summary.enabled_accounts : '-'}</strong><span>{t('overview.ofAccounts', { count: summary?.accounts ?? 0 })}</span></div><div><p>{t('overview.requests')}</p><strong>{formatCount(summary?.requests)}</strong><span>{t('overview.inFlight', { count: summary?.in_flight ?? 0 })}</span></div><div><p>{t('overview.tokens')}</p><strong>{summary ? formatCount(summary.input_tokens+summary.output_tokens) : '-'}</strong><span>{t('overview.tokensDetail')}</span></div><div><p>{t('overview.cache')}</p><strong>{summary ? formatCount(summary.cache_read_tokens ?? 0) : '-'}</strong><span>{t('overview.cacheDetail')}</span></div><div><p>{t('overview.success')}</p><strong>{successRate == null ? '-' : t('common.percent', { value: successRate })}</strong><span>{t('overview.errors', { count: summary?.errors ?? 0 })}</span></div></div>
	<div class="section-toolbar"><div><h2>{t('overview.recent')}</h2><p>{t('overview.recentDescription')}</p></div><button class="button subtle" onclick={() => navigate('activity')}>{t('overview.viewAll')}<ArrowUpRight size={14}/></button></div>
	<section class="ledger">{#if !calls.length}<EmptyState title={t('overview.emptyTitle')} description={t('overview.emptyDescription')} action={t('overview.openQuickstart')} onclick={() => navigate('quickstart')}/>{:else}<div class="table-scroll"><table><thead><tr><th>{t('table.model')}</th><th>{t('table.provider')}</th><th>{t('table.time')}</th><th>{t('table.status')}</th><th>{t('table.duration')}</th></tr></thead><tbody>{#each calls.slice(0,8) as call (call.id)}<tr><td>{call.model}</td><td class="muted">{providerName(call.provider)}</td><td class="muted small">{formatDate(call.started_at)}</td><td><span class="http-status" class:error={call.status >= 400 || !!call.error}>{call.error ? t('table.error') : call.status}</span></td><td class="tabular muted">{call.latency_ms == null ? '-' : `${call.latency_ms} ms`}</td></tr>{/each}</tbody></table></div>{/if}</section>
{:else if screen === 'models'}
	<div class="page-heading"><div><h1>{t('nav.models')}</h1><p class="page-description">{t('models.description')}</p></div><span class="muted small">{t('models.count', { count: models.length })}</span></div>
	<div class="section-toolbar"><p>{t('models.endpoint')} <span class="inline-code">/v1/models</span></p><label class="search-input"><Search size={15}/><input type="search" bind:value={search} aria-label={t('models.search')} placeholder={t('models.search')}/></label></div>
	<section class="ledger">{#if !models.length}<EmptyState title={t('models.emptyTitle')} description={t('models.emptyDescription')} action={t('models.addAccount')} onclick={() => navigate('accounts')}/>{:else if !filteredModels.length}<EmptyState title={t('models.noMatchTitle')} description={t('models.noMatchDescription')}/>{:else}<div class="table-scroll"><table><thead><tr><th>{t('table.model')}</th><th>{t('table.id')}</th><th>{t('table.provider')}</th><th>{t('table.context')}</th><th>{t('table.available')}</th></tr></thead><tbody>{#each filteredModels as model (`${model.provider}:${model.id}`)}<tr><td>{model.name ?? model.id}</td><td class="account-filename">{model.id}</td><td><span class="inline-provider"><ProviderMark provider={model.provider} size={17}/>{providerName(model.provider)}</span></td><td class="tabular muted">{formatCount(model.context_length ?? undefined)}</td><td><button class="switch" class:on={model.enabled !== false} role="switch" aria-checked={model.enabled !== false} aria-label={t('common.enable', { name: model.name ?? model.id })} disabled={!!busy} onclick={() => toggleModel(model)}><span></span></button></td></tr>{/each}</tbody></table></div>{/if}</section>
{:else if screen === 'activity'}
	<div class="page-heading"><div><h1>{t('activity.title')}</h1><p class="page-description">{t('activity.description')}</p></div><span class="muted small">{t('activity.count', { count: calls.length })}</span></div>
	<div class="section-toolbar"><label class="check-label"><input type="checkbox" bind:checked={onlyErrors}/>{t('activity.onlyErrors')}</label><label class="search-input"><Search size={15}/><input type="search" bind:value={search} aria-label={t('activity.search')} placeholder={t('activity.searchPlaceholder')}/></label></div>
	<section class="ledger">{#if !filteredCalls.length}<EmptyState title={t(calls.length ? 'activity.noMatchTitle' : 'activity.emptyTitle')} description={t(calls.length ? 'activity.noMatchDescription' : 'activity.emptyDescription')}/>{:else}<div class="table-scroll"><table><thead><tr><th>{t('table.time')}</th><th>{t('table.modelAccount')}</th><th>{t('table.provider')}</th><th>{t('table.status')}</th><th>{t('table.duration')}</th><th>{t('table.tokens')}</th></tr></thead><tbody>{#each filteredCalls as call (call.id)}<tr><td class="muted small">{formatDate(call.started_at)}</td><td>{call.model}<div class="account-filename">{privateLabel(accounts.find(a => a.id === call.account_id)?.name ?? call.account_id ?? t('activity.unknownAccount'),showEmails)}{#if call.client_id && clientNames.has(call.client_id)}<span class="client-tag" title={t('activity.client', { name: clientNames.get(call.client_id) ?? '' })}>{clientNames.get(call.client_id)}</span>{/if}</div>{#if call.error}<p class="inline-error">{call.error}</p>{/if}</td><td class="muted">{providerName(call.provider)}</td><td><span class="http-status" class:error={call.status >= 400 || !!call.error}>{call.error ? t('table.error') : call.status}</span></td><td class="tabular muted">{call.latency_ms == null ? '-' : `${call.latency_ms} ms`}</td><td class="tabular muted">{formatCount((call.input_tokens ?? 0)+(call.output_tokens ?? 0))}</td></tr>{/each}</tbody></table></div>{/if}</section>
{:else if screen === 'quickstart'}
	<div class="page-heading"><h1>{t('nav.setupTool')}</h1></div>
	<div class="tool-tabs" aria-label={t('quickstart.chooseTool')}><button class="button" class:primary={tool === 'openai'} aria-pressed={tool === 'openai'} onclick={() => { tool = 'openai'; copied = false; copyFailure = ''; }}>{t('provider.openaiCompatible')}</button><button class="button" class:primary={tool === 'claude'} aria-pressed={tool === 'claude'} onclick={() => { tool = 'claude'; copied = false; copyFailure = ''; }}>Claude Code</button></div>
	<div class="setup-guide">
		{#if !accounts.length}<section><div><h2>{t('common.connectAccount')}</h2><button class="button" onclick={() => navigate('accounts')}>{t('quickstart.openAccounts')}<ArrowUpRight size={18}/></button></div></section>{/if}
		{#if tool === 'openai'}<section><div><h2>{t('quickstart.baseUrl')}</h2><div class="copy-field"><code>{baseUrl}</code><button class="icon-button" onclick={() => copy(baseUrl)} aria-label={t('quickstart.copyUrl')}>{#if copied}<Check size={20}/>{:else}<Copy size={20}/>{/if}</button></div><p>{t('quickstart.openaiHint1')}<code class="inline-code">dk_...</code>{t('quickstart.openaiHint2')}</p>{#if summary && !summary.clients}<p class="key-required">{t('quickstart.keyRequired')}</p>{/if}<button class="button" onclick={() => navigate('models')}>{t('quickstart.chooseModel')}<ArrowUpRight size={18}/></button></div></section>
		{:else}<section><div><h2>Claude Code</h2><p>{t('quickstart.powershell')}</p><div class="copy-field config-code"><pre><code>{claudeConfig}</code></pre><button class="icon-button" onclick={() => copy(claudeConfig)} aria-label={t('quickstart.copyClaude')}>{#if copied}<Check size={20}/>{:else}<Copy size={20}/>{/if}</button></div><p>{t('quickstart.claudeHint')}</p>{#if summary && !summary.clients}<p class="key-required">{t('quickstart.keyRequired')}</p>{/if}{#if !accounts.some(account => account.provider === 'claude' && account.enabled)}<button class="button" onclick={() => navigate('accounts')}>{t('quickstart.connectClaude')}<ArrowUpRight size={18}/></button>{/if}</div></section>{/if}
		{#if copyFailure}<p class="inline-error" role="alert">{copyFailure}</p>{/if}
	</div>
{/if}

<style>
	.overview-stats { display: grid; grid-template-columns: repeat(5,1fr); border: 1px solid var(--border); border-radius: 14px; background: var(--surface); margin: 28px 0 34px; }.overview-stats>div { padding: 24px 20px; border-right: 1px solid var(--border); }.overview-stats>div:last-child { border: 0; }.overview-stats p { font-size: 15px; color: var(--muted); margin: 0 0 15px; }.overview-stats strong { display: block; font-family: var(--font-display); font-size: 34px; font-weight: 600; letter-spacing: -.045em; font-variant-numeric: tabular-nums; }.overview-stats span { font-size: 15px; color: var(--faint); display: block; margin-top: 12px; }
	.inline-provider { display: inline-flex; gap: 8px; align-items: center; }.http-status { font-size: 15px; color: var(--green); background: #4dd4ac09; border: 1px solid #4dd4ac20; padding: 4px 7px; border-radius: 6px; }.http-status.error { color: var(--red); background: #ff819509; border-color: #ff819530; }.account-filename { font-family: var(--account-font); font-size: 15px; color: var(--muted); margin-top: 5px; }.inline-error { max-width: 400px; font-size: 15px; color: var(--red); }.check-label { display: inline-flex; align-items: center; gap: 8px; font-size: 15px; color: var(--muted); }.check-label input { accent-color: var(--primary); }.table-scroll { overflow-x: auto; }.client-tag { display: inline-block; margin-left: 9px; padding: 1px 8px; border: 1px solid #7899ff40; border-radius: 6px; background: #5478f61c; color: #c4d3ff; font-size: 13px; vertical-align: 1px; }.setup-guide .key-required { color: var(--yellow); }
	.setup-guide { max-width: 760px; margin-top: 30px; }.setup-guide section { display: flex; gap: 22px; border-bottom: 1px solid var(--border); padding: 28px 0; }.setup-guide section:first-child { padding-top: 0; }.setup-guide h2 { font-size: 16px; margin: 5px 0 12px; }.setup-guide p { color: var(--muted); font-size: 15px; line-height: 1.7; max-width: 600px; }.copy-field { display: flex; align-items: center; justify-content: space-between; border: 1px solid var(--border); background: var(--surface); border-radius: 10px; padding: 9px 13px; margin: 18px 0; }
	.tool-tabs { display: flex; flex-wrap: wrap; gap: 12px; }.setup-guide section>div { width: 100%; min-width: 0; }.setup-guide h2 { font-size: 20px; }.copy-field code { font-size: 16px; overflow-wrap: anywhere; }.config-code { align-items: flex-start; gap: 12px; }.config-code pre { min-width: 0; margin: 7px 0; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.8; }
	/* The request search keeps its own row on a phone, whatever the filter label's length. */
	@media(max-width:780px) { .check-label { flex-basis: 100%; } }
	@media(max-width:700px) { .overview-stats { grid-template-columns: repeat(2,1fr); }.overview-stats>div { padding: 18px; border-bottom: 1px solid var(--border); }.overview-stats strong { font-size: 26px; } }
</style>
